import json, os, subprocess, sys, glob, datetime
RUN = os.path.expanduser('~/.local/state/md-manager-workflows/parallel-reviewers/parallel-reviewers-001')
now = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M:%SZ')
print(f'# tick {now}')
print('## events'); print(open(f'{RUN}/events.jsonl').read().strip().splitlines()[-5:] and '\n'.join(open(f'{RUN}/events.jsonl').read().strip().splitlines()[-5:]))
for f in sorted(glob.glob(f'{RUN}/*.completion.json')): print('COMPLETION', f); print(open(f).read()[:1500])
if os.path.isdir(f'{RUN}/verification'): print('VERIFICATION DIR:', subprocess.run(['find', f'{RUN}/verification', '-maxdepth', '4', '-name', '*.json'], capture_output=True, text=True).stdout)
for lane in ('ui', 'adapter'):
    wt = f'{RUN}/worktree-{lane}'
    enc = wt.replace('/', '-')
    tr = glob.glob(os.path.expanduser(f'~/.claude/projects/{enc}/*.jsonl'))
    print(f'\n## {lane}')
    for t in tr:
        edits, reads, bashes, texts = [], [], [], []
        last_ts = None
        for line in open(t):
            try: o = json.loads(line)
            except Exception: continue
            last_ts = o.get('timestamp', last_ts)
            m = o.get('message') or {}
            c = m.get('content')
            if not isinstance(c, list): continue
            for b in c:
                if not isinstance(b, dict): continue
                if b.get('type') == 'tool_use':
                    n, i = b.get('name'), b.get('input', {})
                    if n in ('Edit', 'Write', 'MultiEdit'): edits.append(i.get('file_path', '?').replace(wt + '/', ''))
                    elif n == 'Read': reads.append(i.get('file_path', '?').replace(wt + '/', ''))
                    elif n == 'Bash': bashes.append((i.get('command') or '')[:160].replace('\n', ' '))
                elif b.get('type') == 'text' and m.get('role') == 'assistant' and b.get('text', '').strip():
                    texts.append(b['text'].strip()[:400])
        print(f'transcript {os.path.basename(t)} last activity {last_ts}')
        print(f'reads({len(reads)}):', ', '.join(dict.fromkeys(reads)))
        print(f'edits({len(edits)}):', ', '.join(dict.fromkeys(edits)))
        print(f'bash({len(bashes)}):'); [print('  $', b) for b in bashes[-12:]]
        print('last assistant text:'); [print('  >', x.replace('\n', ' ')[:400]) for x in texts[-3:]]
    st = subprocess.run(['git', '-C', wt, 'status', '--short', '--untracked-files=all'], capture_output=True, text=True).stdout
    st = '\n'.join(l for l in st.splitlines() if not l.startswith('?? node_modules') and '/.venv' not in l)
    print('git status:\n' + (st or '  (clean)'))
    print(subprocess.run(['git', '-C', wt, 'diff', '--stat'], capture_output=True, text=True).stdout)
EOF
